import boto3
from botocore.exceptions import ClientError

from .base import NoSuchBucket, ObjectStore


class S3Store(ObjectStore):
    def __init__(self, endpoint_url: str, access_key: str, secret_key: str) -> None:
        self.s3 = boto3.client(
            "s3",
            endpoint_url=endpoint_url,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key,
            region_name="us-east-1",
        )

    def create_bucket(self, bucket: str) -> None:
        try:
            self.s3.create_bucket(Bucket=bucket)
        except self.s3.exceptions.BucketAlreadyOwnedByYou:
            pass

    def put(self, bucket: str, key: str, data: bytes) -> None:
        self._call(self.s3.put_object, Bucket=bucket, Key=key, Body=data)

    def get(self, bucket: str, key: str) -> bytes:
        return self._call(self.s3.get_object, Bucket=bucket, Key=key)["Body"].read()

    def list_keys(self, bucket: str, prefix: str = "") -> list[str]:
        page = self._call(self.s3.list_objects_v2, Bucket=bucket, Prefix=prefix)
        return [item["Key"] for item in page.get("Contents", [])]

    def _call(self, method, **kwargs):
        try:
            return method(**kwargs)
        except ClientError as error:
            if error.response["Error"]["Code"] == "NoSuchBucket":
                raise NoSuchBucket(kwargs["Bucket"]) from error
            raise
